const axios = require('axios');

async function getAcepThinkerData(m) {
  const url = 'https://www.acethinker.ai/downloader/api/dlapinewv2.php';
  const videoUrl = 'https://youtu.be/ObuP-wH0ghA?si=pwdwhVr8cZLBgXAh';
  const csrfToken = '56f502cba23c3bbf5ec816e067319867f5d82aaf8445d75685222518fd506cbea0403d1eb8b5c50d97f06710a5422a0772adabb5ce05f66944938b88827363e5';

  try {
    const response = await axios.get(url, {
      params: {
        url: videoUrl
      },
      headers: {
        'Accept': 'application/json, text/plain, */*',
        'X-CSRF-Token': csrfToken
      }
    });

    const data = response.data;

    if (data && data.res_data) {
      const title = data.res_data.title;
      const thumbnail = data.res_data.thumbnail;
      const formats = data.res_data.formats;

      let message = `Judul: ${title}\nThumbnail: ${thumbnail}\n\nFormat Tersedia:\n`;

      formats.forEach(format => {
        message += `- Kualitas: ${format.quality}, Ukuran: ${(format.filesize / 1024 / 1024).toFixed(2)} MB, Ekstensi: ${format.ext}\n`;
      });

      await m.reply(message);
    } else {
      await m.reply('Gagal mendapatkan data dari server.');
    }
  } catch (error) {
    await m.reply(`Terjadi kesalahan: ${error.message}`);
  }
}
